WITH matched_keys AS (SELECT product_id, id FROM inventory EXCEPT SELECT product_id, id FROM inventory WHERE quantity >= 79), reconciled AS (SELECT s.* FROM inventory s INNER JOIN matched_keys k ON s.product_id = k.product_id AND s.id = k.id) SELECT s.store_id, s.last_restock, (SELECT SUM(x.discount) FROM orders x WHERE x.store_id = s.store_id) AS sum_order_discount FROM reconciled s ORDER BY last_restock
